#include <vector>
#include <numeric>

class Solution {
public:
    int findMiddleIndex(std::vector<int>& nums) {
        long long total = 0;
        for (int x : nums) total += x;
        long long leftSum = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (leftSum == total - leftSum - nums[i]) return i;
            leftSum += nums[i];
        }
        return -1;
    }
};

class Solution {
    public int findMiddleIndex(int[] nums) {
        long total = 0;
        for (int x : nums) total += x;
        long leftSum = 0;
        for (int i = 0; i < nums.length; i++) {
            if (leftSum == total - leftSum - nums[i]) return i;
            leftSum += nums[i];
        }
        return -1;
    }
}

